// Bookmark Manager API — entrypoint
// See PRODUCT_SPEC.md for full requirements
// The agent will build this out across tasks T1-T6

import express, { NextFunction, Request, Response } from "express";
import Database from "better-sqlite3";
import bcrypt from "bcryptjs";
import jwt, { JwtPayload } from "jsonwebtoken";

const app = express();
const PORT = process.env.PORT || 3000;
const db = new Database("data.db");
db.pragma("foreign_keys = ON");
const JWT_SECRET = "benchmark-secret";

app.use(express.json());

type Bookmark = {
  id: number;
  user_id: number;
  url: string;
  title: string;
  description: string | null;
  folder_id: number | null;
  created_at: string;
  updated_at: string;
};

type Tag = {
  id: number;
  user_id: number;
  name: string;
  created_at: string;
  updated_at: string;
};

type BookmarkWithTags = Bookmark & {
  tags: Tag[];
};

type Folder = {
  id: number;
  user_id: number;
  name: string;
  created_at: string;
  updated_at: string;
};

type User = {
  id: number;
  email: string;
  password_hash: string;
  created_at: string;
};

type PublicUser = Omit<User, "password_hash">;

type AuthenticatedRequest = Request & {
  userId: number;
};

type CountRow = {
  total: number;
};

db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    created_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS folders (
    id INTEGER PRIMARY KEY,
    user_id INTEGER,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id)
  );

  CREATE TABLE IF NOT EXISTS bookmarks (
    id INTEGER PRIMARY KEY,
    user_id INTEGER,
    url TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    folder_id INTEGER,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id),
    FOREIGN KEY (folder_id) REFERENCES folders(id)
  );

  CREATE TABLE IF NOT EXISTS tags (
    id INTEGER PRIMARY KEY,
    user_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE (user_id, name),
    FOREIGN KEY (user_id) REFERENCES users(id)
  );

  CREATE TABLE IF NOT EXISTS bookmark_tags (
    bookmark_id INTEGER NOT NULL,
    tag_id INTEGER NOT NULL,
    PRIMARY KEY (bookmark_id, tag_id),
    FOREIGN KEY (bookmark_id) REFERENCES bookmarks(id) ON DELETE CASCADE,
    FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE
  )
`);

const folderColumns = db.prepare("PRAGMA table_info(folders)").all() as Array<{ name: string }>;
if (!folderColumns.some((column) => column.name === "user_id")) {
  db.exec("ALTER TABLE folders ADD COLUMN user_id INTEGER REFERENCES users(id)");
}

const bookmarkColumns = db.prepare("PRAGMA table_info(bookmarks)").all() as Array<{ name: string }>;
if (!bookmarkColumns.some((column) => column.name === "folder_id")) {
  db.exec("ALTER TABLE bookmarks ADD COLUMN folder_id INTEGER REFERENCES folders(id)");
}
if (!bookmarkColumns.some((column) => column.name === "user_id")) {
  db.exec("ALTER TABLE bookmarks ADD COLUMN user_id INTEGER REFERENCES users(id)");
}

const selectBookmarkById = db.prepare("SELECT * FROM bookmarks WHERE id = ? AND user_id = ?");
const selectFolderById = db.prepare("SELECT * FROM folders WHERE id = ? AND user_id = ?");
const selectTagById = db.prepare("SELECT * FROM tags WHERE id = ? AND user_id = ?");
const selectTagByName = db.prepare("SELECT * FROM tags WHERE name = ? AND user_id = ?");
const selectUserByEmail = db.prepare("SELECT * FROM users WHERE email = ?");
const selectUserById = db.prepare("SELECT * FROM users WHERE id = ?");

function getBookmark(id: number, userId: number): Bookmark | undefined {
  return selectBookmarkById.get(id, userId) as Bookmark | undefined;
}

function getFolder(id: number, userId: number): Folder | undefined {
  return selectFolderById.get(id, userId) as Folder | undefined;
}

function getTag(id: number, userId: number): Tag | undefined {
  return selectTagById.get(id, userId) as Tag | undefined;
}

function getBookmarkTags(bookmarkId: number, userId: number): Tag[] {
  return db
    .prepare(
      `
        SELECT tags.*
        FROM tags
        INNER JOIN bookmark_tags ON bookmark_tags.tag_id = tags.id
        WHERE bookmark_tags.bookmark_id = ? AND tags.user_id = ?
        ORDER BY tags.id ASC
      `,
    )
    .all(bookmarkId, userId) as Tag[];
}

function attachTagsToBookmark(bookmark: Bookmark, userId: number): BookmarkWithTags {
  return {
    ...bookmark,
    tags: getBookmarkTags(bookmark.id, userId),
  };
}

function attachTagsToBookmarks(bookmarks: Bookmark[], userId: number): BookmarkWithTags[] {
  if (bookmarks.length === 0) {
    return [];
  }

  const bookmarkIds = bookmarks.map((bookmark) => bookmark.id);
  const placeholders = bookmarkIds.map(() => "?").join(", ");
  const rows = db
    .prepare(
      `
        SELECT bookmark_tags.bookmark_id, tags.*
        FROM bookmark_tags
        INNER JOIN tags ON tags.id = bookmark_tags.tag_id
        WHERE tags.user_id = ? AND bookmark_tags.bookmark_id IN (${placeholders})
        ORDER BY tags.id ASC
      `,
    )
    .all(userId, ...bookmarkIds) as Array<Tag & { bookmark_id: number }>;
  const tagsByBookmark = new Map<number, Tag[]>();

  for (const row of rows) {
    const tags = tagsByBookmark.get(row.bookmark_id) ?? [];
    const { bookmark_id: _bookmarkId, ...tag } = row;
    tags.push(tag);
    tagsByBookmark.set(row.bookmark_id, tags);
  }

  return bookmarks.map((bookmark) => ({
    ...bookmark,
    tags: tagsByBookmark.get(bookmark.id) ?? [],
  }));
}

function parseId(value: unknown): number | null {
  if (typeof value !== "string") {
    return null;
  }

  const id = Number(value);
  return Number.isInteger(id) && id > 0 ? id : null;
}

function parsePaginationParam(
  value: unknown,
  defaultValue: number,
  min: number,
  max: number,
): number | string {
  if (value === undefined) {
    return defaultValue;
  }

  if (Array.isArray(value) || typeof value !== "string" || !/^\d+$/.test(value)) {
    return "must be an integer";
  }

  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed) || parsed < min || parsed > max) {
    return `must be between ${min} and ${max}`;
  }

  return parsed;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function validateRequiredNonEmptyString(input: Record<string, unknown>, field: string): string | null {
  if (!(field in input) || !isNonEmptyString(input[field])) {
    return `${field} must be a non-empty string`;
  }

  return null;
}

function validateOptionalNonEmptyString(input: Record<string, unknown>, field: string): string | null {
  if (field in input && !isNonEmptyString(input[field])) {
    return `${field} must be a non-empty string`;
  }

  return null;
}

function isValidEmail(value: unknown): value is string {
  if (!isNonEmptyString(value)) {
    return false;
  }

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

