    return res.status(400).json({ error: input });
  }

  const existing = selectUserByEmail.get(input.email) as User | undefined;
  if (existing) {
    return res.status(409).json({ error: "Email already exists" });
  }

  const now = new Date().toISOString();
  const passwordHash = bcrypt.hashSync(input.password, 10);
  const result = db
    .prepare(
      `
        INSERT INTO users (email, password_hash, created_at)
        VALUES (?, ?, ?)
      `,
    )
    .run(input.email, passwordHash, now);

  const user = selectUserById.get(Number(result.lastInsertRowid)) as User;
  res.status(201).json(toPublicUser(user));
});

app.post("/auth/login", (req, res) => {
  const input = validateAuthInput(req.body, false);
  if (typeof input === "string") {
    return res.status(400).json({ error: input });
  }

  const user = selectUserByEmail.get(input.email) as User | undefined;
  if (!user || !bcrypt.compareSync(input.password, user.password_hash)) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = jwt.sign({ userId: user.id }, JWT_SECRET);
  res.status(200).json({ token });
});

