app.get("/bookmarks", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const page = parsePaginationParam(req.query.page, 1, 1, Number.MAX_SAFE_INTEGER);
  if (typeof page === "string") {
    return res.status(400).json({ error: `page ${page}` });
  }

  const limit = parsePaginationParam(req.query.limit, 20, 1, 100);
  if (typeof limit === "string") {
    return res.status(400).json({ error: `limit ${limit}` });
  }

  const tagFilters = parseTagFilters(req.query.tag, req.query.tags);
  if (typeof tagFilters === "string") {
    return res.status(400).json({ error: tagFilters });
  }

  const searchQuery = parseSearchQuery(req.query.q);
  if (searchQuery.error) {
    return res.status(400).json({ error: searchQuery.error });
  }

  const offset = (page - 1) * limit;
  const whereParts = ["bookmarks.user_id = ?"];
  const filterParams: unknown[] = [userId];
  if (tagFilters.length > 0) {
    const placeholders = tagFilters.map(() => "?").join(", ");
    whereParts.push(`
      bookmarks.id IN (
        SELECT bookmark_tags.bookmark_id
        FROM bookmark_tags
        INNER JOIN tags ON tags.id = bookmark_tags.tag_id
        WHERE tags.user_id = ? AND tags.name IN (${placeholders})
        GROUP BY bookmark_tags.bookmark_id
        HAVING COUNT(DISTINCT tags.name) = ?
      )
    `);
    filterParams.push(userId, ...tagFilters, tagFilters.length);
  }

  let orderBy = "bookmarks.id ASC";
  const orderParams: unknown[] = [];
  if (searchQuery.value !== null) {
    const normalizedQuery = searchQuery.value.toLowerCase();
    const escapedQuery = escapeLikePattern(normalizedQuery);
    const containsPattern = `%${escapedQuery}%`;
    const prefixPattern = `${escapedQuery}%`;

    whereParts.push(`
      (
        LOWER(bookmarks.title) LIKE ? ESCAPE '\\'
        OR LOWER(bookmarks.url) LIKE ? ESCAPE '\\'
        OR LOWER(COALESCE(bookmarks.description, '')) LIKE ? ESCAPE '\\'
        OR EXISTS (
          SELECT 1
          FROM folders
          WHERE folders.id = bookmarks.folder_id
            AND folders.user_id = ?
            AND LOWER(folders.name) LIKE ? ESCAPE '\\'
        )
        OR EXISTS (
          SELECT 1
          FROM bookmark_tags
          INNER JOIN tags ON tags.id = bookmark_tags.tag_id
          WHERE bookmark_tags.bookmark_id = bookmarks.id
            AND tags.user_id = ?
            AND LOWER(tags.name) LIKE ? ESCAPE '\\'
        )
      )
    `);
    filterParams.push(containsPattern, containsPattern, containsPattern, userId, containsPattern, userId, containsPattern);
    orderBy = `
      CASE
        WHEN LOWER(bookmarks.title) = ? THEN 0
        WHEN LOWER(bookmarks.title) LIKE ? ESCAPE '\\' THEN 1
        WHEN LOWER(bookmarks.title) LIKE ? ESCAPE '\\' THEN 2
        ELSE 3
      END,
      bookmarks.id ASC
    `;
    orderParams.push(normalizedQuery, prefixPattern, containsPattern);
  }

  const whereClause = whereParts.join(" AND ");
  const { total } = db
    .prepare(`SELECT COUNT(*) AS total FROM bookmarks WHERE ${whereClause}`)
    .get(...filterParams) as CountRow;
  const bookmarks = db
    .prepare(`SELECT * FROM bookmarks WHERE ${whereClause} ORDER BY ${orderBy} LIMIT ? OFFSET ?`)
    .all(...filterParams, ...orderParams, limit, offset) as Bookmark[];

  res.status(200).json({
    data: attachTagsToBookmarks(bookmarks, userId),
    page,
    limit,
    total,
  });
});

